{"task_id": "T45", "code": "def solve(words, k):
    from collections import Counter
    if k <= 0:
        return []
    cnt = Counter(words)
    # sort by frequency descending, then word ascending
    sorted_items = sorted(cnt.items(), key=lambda x: (-x[1], x[0]))
    if not sorted_items:
        return []
    # Determine cutoff frequency
    if k >= len(sorted_items):
        cutoff_index = len(sorted_items) - 1
    else:
        cutoff_freq = sorted_items[k-1][1]
        # include all items with freq >= cutoff_freq
        cutoff_index = k-1
        # extend while next items have same freq
        while cutoff_index + 1 < len(sorted_items) and sorted_items[cutoff_index + 1][1] == cutoff_freq:
            cutoff_index += 1
    return [w for w, _ in sorted_items[:cutoff_index+1]]"}

