{"task_id": "T21", "code": "def solve(weights, values, capacity):
    """0/1 knapsack returning maximum total value.
    Uses DP when size is moderate, otherwise meet-in-the-middle.
    """
    n = len(weights)
    if n == 0 or capacity <= 0:
        return 0
    # If DP table is reasonably sized, use classic DP
    if n * capacity <= 5_000_000:
        dp = [0] * (capacity + 1)
        for w, v in zip(weights, values):
            if w > capacity:
                continue
            for c in range(capacity, w - 1, -1):
                new_val = dp[c - w] + v
                if new_val > dp[c]:
                    dp[c] = new_val
        return dp[capacity]
    # Otherwise, meet-in-the-middle approach
    from itertools import combinations
    half = n // 2
    w1, v1 = weights[:half], values[:half]
    w2, v2 = weights[half:], values[half:]
    # enumerate all subsets of first half
    subs1 = []
    for r in range(len(w1) + 1):
        for combo in combinations(range(len(w1)), r):
            total_w = sum(w1[i] for i in combo)
            if total_w <= capacity:
                total_v = sum(v1[i] for i in combo)
                subs1.append((total_w, total_v))
    # enumerate all subsets of second half
    subs2 = []
    for r in range(len(w2) + 1):
        for combo in combinations(range(len(w2)), r):
            total_w = sum(w2[i] for i in combo)
            if total_w <= capacity:
                total_v = sum(v2[i] for i in combo)
                subs2.append((total_w, total_v))
    # sort and prune subs2 to keep only max value for each weight prefix
    subs2.sort()
    pruned = []
    max_val = -1
    for w, v in subs2:
        if v > max_val:
            pruned.append((w, v))
            max_val = v
    # binary search best partner for each entry from subs1
    import bisect
    weights_pruned = [w for w, _ in pruned]
    values_pruned = [v for _, v in pruned]
    best = 0
    for w1_val, v1_val in subs1:
        remaining = capacity - w1_val
        idx = bisect.bisect_right(weights_pruned, remaining) - 1
        if idx >= 0:
            total = v1_val + values_pruned[idx]
            if total > best:
                best = total
    return best"}

