def solve(path):
    """Simplify a Unix-style absolute path.
    Resolve '.' and '..', collapse multiple slashes, and remove trailing slash.
    The result always starts with '/' and '/' is returned for the root.
    """
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)
    return '/' + '/'.join(stack)

