def solve(matrix):
    """Return determinant of integer square matrix.
    Empty matrix -> 1.
    """
    # Helper recursive determinant
    def det(m):
        n = len(m)
        if n == 0:
            return 1
        if n == 1:
            return m[0][0]
        if n == 2:
            return m[0][0]*m[1][1] - m[0][1]*m[1][0]
        # Use expansion on first row
        total = 0
        for col in range(n):
            # Skip zero elements for efficiency
            a = m[0][col]
            if a == 0:
                continue
            # Build minor matrix
            minor = [row[:col] + row[col+1:] for row in m[1:]]
            sign = -1 if col % 2 else 1
            total += sign * a * det(minor)
        return total
    # Validate square matrix
    if not matrix:
        return 1
    n = len(matrix)
    for row in matrix:
        if len(row) != n:
            raise ValueError('Matrix must be square')
    return det(matrix)

def solve(n, b):
    """Convert integer n to a string representation in base b (2 <= b <= 36).
    Uses digits 0-9 and a-z for values 10-35. Negative numbers get a leading '-'.
    """
    if not isinstance(b, int) or b < 2 or b > 36:
        raise ValueError('Base must be an integer between 2 and 36')
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    if n == 0:
        return '0'
    neg = n < 0
    n = -n if neg else n
    res = []
    while n:
        n, rem = divmod(n, b)
        res.append(digits[rem])
    if neg:
        res.append('-')
    return ''.join(reversed(res))

