    import bisect
    if not nums:
        return 0
    tails = []
    for x in nums:
        # Find position to replace in tails; bisect_left ensures strictly increasing
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

