    """Return the length of the longest substring (or sub‑sequence) without repeating elements.
    Works for strings and any iterable of hashable items. If the input is not iterable
    or contains unhashable elements, returns 0.
    """
    try:
        iterator = iter(s)
    except Exception:
        return 0
    last = {}
    start = 0
    max_len = 0
    for i, ch in enumerate(s):
        try:
            prev = last.get(ch)
        except Exception:
            # unhashable element – cannot track, abort safely
            return 0
        if prev is not None and prev >= start:
