def solve(line):
    fields = []
    field = []
    i = 0
    n = len(line)
    in_quotes = False
    while i < n:
        ch = line[i]
        if in_quotes:
            if ch == '"':
                # look ahead for double quote
                if i + 1 < n and line[i+1] == '"':
                    field.append('"')
                    i += 1  # skip next quote
                else:
                    in_quotes = False
            else:
                field.append(ch)
        else:
            if ch == '"':
                in_quotes = True
            elif ch == ',':
                fields.append(''.join(field))
                field = []
            else:
                field.append(ch)
        i += 1
    # Append last field
