    Meetings with start > end are considered invalid and ignored.
    """
    # Filter valid meetings
    valid = []
    for m in meetings:
        try:
            s, e = m[0], m[1]
        except Exception:
            continue
        if not isinstance(s, (int, float)) or not isinstance(e, (int, float)):
            continue
        if s > e:
            continue
        valid.append((s, e))
    if not valid:
        return 0
    # Sort by end time, then start
    valid.sort(key=lambda x: (x[1], x[0]))
    count = 0
    last_end = -float('inf')
    for s, e in valid:
        if s >= last_end:
            count += 1
            last_end = e
    return count

